function reachable(roots) {
  const seen = new Set(), stack = [...roots]
  while (stack.length) {
    const o = stack.pop()
    if (seen.has(o)) continue
    seen.add(o)
    for (const r of o.refs ?? []) stack.push(r)
  }
  return seen
}

