function lruCache(limit) {
  const m = new Map()
  return {
    get(k) {
      if (!m.has(k)) return undefined
      const v = m.get(k); m.delete(k); m.set(k, v)
      return v
    },
    set(k, v) {
      m.delete(k); m.set(k, v)
      if (m.size > limit) m.delete(m.keys().next().value)
    },
    get size() { return m.size },
  }
}

