function lazy(iterable) {
  return {
    map: (f) => lazy((function* () { for (const x of iterable) yield f(x) })()),
    filter: (f) => lazy((function* () { for (const x of iterable) if (f(x)) yield x })()),
    take: (n) => lazy((function* () { if (n <= 0) return; for (const x of iterable) { yield x; if (--n === 0) return } })()),
    toArray: () => [...iterable],
  }
}

