function debounce(fn, ms) {
  let t
  const d = (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms) }
  d.cancel = () => clearTimeout(t)
  return d
}
function throttle(fn, ms) {
  let last = -Infinity
  return (...a) => {
    const now = Date.now()
    if (now - last >= ms) { last = now; fn(...a) }
  }
}

