async function processInChunks(items, chunkSize, fn) {
  const out = []
  for (let i = 0; i < items.length; i += chunkSize) {
    for (const x of items.slice(i, i + chunkSize)) out.push(fn(x))
    await new Promise((r) => setTimeout(r))
  }
  return out
}
